  const s=this.state,rows=this.rewardPool(kind),cost=this.rewardCost(kind),quota=this.paidBoostInfo();if(!rows.length||!cost||(free?(kind!=='hourly'||now<s.rewardReadyAt):s[cost.currency]<cost.amount)||(kind==='hourly'&&!free&&quota.remaining<1)||(kind==='skin'&&((character==='Tia'&&!s.tiaUnlocked)||!this.eligibleSkins(character).length)))return null;
